const items = $input.all();
const articles = [];
const seen = new Set();

// Fixed website IDs
const sourceIds = {
  "TechCrunch": 100,
  "MIT Technology Review": 200,
  "MarkTechPost": 300
};

for (const item of items) {
  const data = item.json.data || {};
  const content = data.content || "";

  // Extract Markdown links
  const regex =
    /\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)(?:\s+"[^"]*")?\)/g;

  for (const match of content.matchAll(regex)) {

    let title = match[1].trim();
    const url = match[2].trim();

    // Remove invalid titles and images
    if (!title || title.startsWith("!")) continue;
    if (/^image\s*\d*:/i.test(title)) continue;
    if (title.length < 25) continue;

    if (/\.(jpg|jpeg|png|svg|webp|gif)(\?|$)/i.test(url)) {
      continue;
    }

    let source = "";
    let valid = false;

    // 1. TECHCRUNCH
    if (
      /^https?:\/\/(www\.)?techcrunch\.com\//i.test(url)
    ) {
      source = "TechCrunch";

      valid =
        /techcrunch\.com\/\d{4}\/\d{2}\/\d{2}\/[^/?]+/i
          .test(url);
    }

    // 2. MIT TECHNOLOGY REVIEW
    else if (
      /^https?:\/\/(www\.)?technologyreview\.com\//i.test(url)
    ) {
      source = "MIT Technology Review";

      valid =
        /technologyreview\.com\/\d{4}\/\d{2}\/\d{2}\/\d+\/[^/?]+/i
          .test(url);
    }

    // 3. MARKTECHPOST
    else if (
      /^https?:\/\/(www\.)?marktechpost\.com\//i.test(url)
    ) {
      source = "MarkTechPost";

      valid =
        /marktechpost\.com\/\d{4}\/\d{2}\/\d{2}\/[^/?]+/i
          .test(url);
    }

    if (!valid) continue;

    // Clean URL
    const cleanUrl = url
      .split("?")[0]
      .split("#")[0];

    // Remove duplicates
    const normalizedUrl = cleanUrl
      .replace(/\/$/, "")
      .toLowerCase();

    if (seen.has(normalizedUrl)) continue;
    seen.add(normalizedUrl);

    // Extract date hint
    const dateMatch = cleanUrl.match(
      /\/(20\d{2})\/(\d{2})\/(\d{2})(?:\/|$)/
    );

    let url_date_hint = null;

    if (dateMatch) {
      const dateString =
        `${dateMatch[1]}-${dateMatch[2]}-${dateMatch[3]}`;

      const parsedDate = new Date(
        dateString + "T00:00:00Z"
      );

      if (
        Number.isFinite(parsedDate.getTime()) &&
        parsedDate.toISOString().slice(0, 10) === dateString
      ) {
        url_date_hint = parsedDate.toISOString();
      }
    }

    // Keep only articles with valid URL dates
    if (!url_date_hint) continue;

    articles.push({
      json: {
        run_id: sourceIds[source],
        source,
        title,
        url: cleanUrl,
        url_date_hint
      }
    });
  }
}

return articles;

const websites = [
  {
    run_id: 100,
    source: "TechCrunch",
    url: "https://techcrunch.com/category/artificial-intelligence/"
  },
  {
    run_id: 200,
    source: "MIT Technology Review",
    url: "https://www.technologyreview.com/topic/artificial-intelligence/"
  },
  {
    run_id: 300,
    source: "MarkTechPost",
    url: "https://www.marktechpost.com/"
  }
];

return websites.map(website => ({
  json: website
}));

/**
 * AI NEWS SCORER - V4
 * n8n Code Node
 * Mode: Run Once for All Items
 *
 * Based on your original scoring algorithm.
 *
 * Preserved:
 * - Recency calculation
 * - Source weights
 * - Impact rules and cap
 * - Niche penalties
 * - Original interest rules
 * - Score formula
 * - Cluster limits
 * - Sorting and qualification logic
 *
 * Added:
 * - Technical AI model release interest (+28)
 * - AI developer API release interest (+28)
 *
 * Threshold: 54
 * Maximum qualified: 35
 * Maximum input: 100
 */

// ======================================================
// CONFIGURATION
// ======================================================

const TOP_N = 35;
const THRESHOLD = 54;
const MAX_ARTICLES = 100;

const DEFAULT_MAX_PER_CLUSTER = 2;

// Recency: [maximum age in days, points]

const RECENCY = [
  [1, 15],
  [3, 12],
  [6, 9],
  [14, 5],
  [30, 2],
];

// Source trust/usefulness weights

const SOURCE_WEIGHT = {
  "MIT Technology Review": 15,
  "TechCrunch": 12,
  "MarkTechPost": 8,
};

// ======================================================
// IMPACT RULES - UNCHANGED
// ======================================================

const IMPACT_RULES = [
  {
    re: /\bipo\b|nasdaq/i,
    pts: 25,
    label: "IPO/market event"
  },
  {
    re: /scandal|ousted|\bexit\b|asked .* to quit/i,
    pts: 15,
    label: "leadership shake-up"
  },
  {
    re: /gemini|gpt-|claude|openai|anthropic|deepmind/i,
    pts: 15,
    label: "major lab"
  },
  {
    re: /cyberattack|hack|breach|unpatchable|exposing private data|security/i,
    pts: 14,
    label: "security"
  },
  {
    re: /regulat|policy|lawsuit|sues/i,
    pts: 12,
    label: "policy/legal"
  },
  {
    re: /riemann|breakthrough|misunderstood graph/i,
    pts: 12,
    label: "research/big picture"
  },
  {
    re: /agent/i,
    pts: 8,
    label: "agents"
  },
  {
    re: /releases?|launch|ships|introduce/i,
    pts: 6,
    label: "release"
  },
];

const IMPACT_CAP = 40;

// ======================================================
// NICHE RULES - UNCHANGED
// ======================================================

const NICHE_RULES = [
  {
    re: /kubernetes|kv cache|gpu kernel|lora|tts\b|git server|emulator|\bsdk\b|gateway|tensorlean/i,
    pts: -12,
    label: "niche dev/infra"
  },
  {
    re: /gadgets|raises \$|funding|financing/i,
    pts: -8,
    label: "funding/gadget"
  },
];

// ======================================================
// INTEREST RULES
// ORIGINAL RULES PRESERVED
// TWO NEW RULES ADDED AT THE END
// ======================================================

const INTERESTS = [
  {
    re: /misunderstood graph|hype index|backlash|economics of the web|fencing it in|circular financing|open-source movement|track chips/i,
    pts: 35,
    label: "interest: big-picture analysis"
  },
  {
    re: /runs on a 32gb mac|runs locally/i,
    pts: 35,
    label: "interest: local/on-device models"
  },
  {
    re: /gemini 4|gpt-6|gpt-live|multiagent|nemotron|diffusion language/i,
    pts: 30,
    label: "interest: frontier model release"
  },
  {
    re: /personal ai agents|runs your mac|use your mac|live in your text/i,
    pts: 25,
    label: "interest: everyday agents"
  },
  {
    re: /cyberattack|hacking tool|breach|unpatchable|exposing private data/i,
    pts: 25,
    label: "interest: AI security incidents"
  },
  {
    re: /jensen|huang/i,
    pts: 25,
    label: "interest: Nvidia leadership story"
  },
  {
    re: /regulate/i,
    pts: 25,
    label: "interest: AI policy"
  },
  {
    re: /riemann/i,
    pts: 25,
    label: "interest: AI research milestone"
  },
  {
    re: /claude code|code mode/i,
    pts: 25,
    label: "interest: dev tools"
  },
  {
    re: /60k employees/i,
    pts: 25,
    label: "interest: big-tech workforce"
  },
  {
    re: /founders cashed out|charity/i,
    pts: -10,
    label: "less interested: payouts/charity angle"
  },

  // ====================================================
  // NEW RULE 1: TECHNICAL AI MODEL RELEASES
  // ====================================================

  {
    re: /(?=.*\b(?:releases?|launches?|ships?|introduces?|unveils?|open.sources?)\b)(?=.*\b(?:agentic|coding model|decision model|search model|language model|reasoning model|foundation model|reinforcement learning)\b).*/i,
    pts: 28,
    label: "interest: technical AI model release"
  },

  // ====================================================
  // NEW RULE 2: AI DEVELOPER API RELEASES
  // ====================================================

  {
    re: /(?=.*\b(?:releases?|launches?|ships?|introduces?|previews?|unveils?)\b)(?=.*\b(?:api|sdk|orchestrator|tool retrieval|model routing)\b).*/i,
    pts: 28,
    label: "interest: AI developer API release"
  },
];

// ======================================================
// TOPIC CLUSTERS - UNCHANGED
// ======================================================

const CLUSTERS = [
  {
    name: "Anthropic IPO",
    max: 5,
    re: /anthropic.*(ipo|nasdaq)|ipo.*anthropic|nasdaq.*anthropic|own nearly 30%/i
  },
  {
    name: "Jensen Huang",
    max: 2,
    re: /jensen|huang/i
  },
  {
    name: "Nadella interviews",
    max: 3,
    re: /nadella/i
  },
];

// ======================================================
// HELPER FUNCTIONS - UNCHANGED
// ======================================================

function cleanTitle(t) {
  return String(t ?? "")
    .replace(/^\d{2}\s+/, "")
    .replace(/\*\*.*$/, "")
    .replace(/\s+(NOV|OCT)\s+\d{1,2},\s+\d{4}$/i, "")
    .trim();
}

function recencyPoints(ageDays) {
  for (const [maxAge, pts] of RECENCY) {
    if (ageDays <= maxAge) {
      return pts;
    }
  }

  return 0;
}

function applyRules(title, rules, cap) {
  let total = 0;
  const reasons = [];

  for (const r of rules) {
    if (r.re.test(title)) {
      total += r.pts;

      reasons.push(
        `${r.label} (${r.pts > 0 ? "+" : ""}${r.pts})`
      );
    }
  }

  if (cap && total > cap) {
    reasons.push(`capped at ${cap}`);
    total = cap;
  }

  return {
    total,
    reasons
  };
}

// ======================================================
// READ INPUT FROM N8N
// ======================================================

const inputItems = $input.all();

const articles = inputItems.flatMap(item => {
  const data = item.json;

  if (Array.isArray(data)) {
    return data;
  }

  if (Array.isArray(data.articles)) {
    return data.articles;
  }

  return [data];
});

if (articles.length > MAX_ARTICLES) {
  throw new Error(
    `Received ${articles.length} articles. ` +
    `Maximum supported is ${MAX_ARTICLES}.`
  );
}

if (articles.length === 0) {
  return [];
}

// ======================================================
// FIND NEWEST ARTICLE DATE
// ======================================================

const newest = Math.max(
  ...articles.map(a =>
    new Date(a.url_date_hint).getTime()
  )
);

// ======================================================
// SCORE ALL ARTICLES
// ======================================================

const scored = articles.map(a => {

  const title = cleanTitle(a.title);

  const ageDays = Math.max(
    0,
    (
      newest -
      new Date(a.url_date_hint).getTime()
    ) / 86400000
  );

  // 1. RECENCY

  const recency = recencyPoints(ageDays);

  // 2. SOURCE

  const source =
    SOURCE_WEIGHT[a.source] ?? 5;

  // 3. IMPACT

  const impact = applyRules(
    title,
    IMPACT_RULES,
    IMPACT_CAP
  );

  // 4. NICHE

  const niche = applyRules(
    title,
    NICHE_RULES
  );

  // 5. INTERESTS

  const interest = applyRules(
    title,
    INTERESTS
  );

  // 6. FINAL SCORE
  // Original formula preserved.

  const score =
    recency +
    source +
    impact.total +
    niche.total +
    interest.total;

  // 7. TOPIC CLUSTER

  const clusterDef = CLUSTERS.find(
    c => c.re.test(title)
  );

  const cluster = clusterDef
    ? clusterDef.name
    : null;

  const clusterMax = clusterDef
    ? clusterDef.max ?? DEFAULT_MAX_PER_CLUSTER
    : null;

  return {

    run_id: a.run_id ?? null,

    title,

    source: a.source,

    date: String(
      a.url_date_hint ?? ""
    ).slice(0, 10),

    url: a.url,

    url_date_hint: a.url_date_hint,

    score,

    cluster,

    clusterMax,

    breakdown: {
      recency,
      source,
      impact: impact.total,
      niche: niche.total,
      interest: interest.total
    },

    reasons: [
      ...impact.reasons,
      ...niche.reasons,
      ...interest.reasons
    ],

    qualifies: false,

    reject_reason: null
  };

});

// ======================================================
// SORT ARTICLES BY SCORE
// ======================================================

scored.sort(
  (a, b) => b.score - a.score
);

// ======================================================
// QUALIFICATION LOGIC - UNCHANGED
// ======================================================

const clusterCount = {};

let kept = 0;

for (const art of scored) {

  if (art.score < THRESHOLD) {

    art.reject_reason =
      `score ${art.score} < threshold ${THRESHOLD}`;

    continue;
  }

  if (art.cluster) {

    clusterCount[art.cluster] =
      (clusterCount[art.cluster] || 0) + 1;

    if (
      clusterCount[art.cluster] >
      art.clusterMax
    ) {

      art.reject_reason =
        `duplicate topic: "${art.cluster}" ` +
        `already has ${art.clusterMax}`;

      continue;
    }
  }

  if (kept >= TOP_N) {

    art.reject_reason =
      `outside top ${TOP_N}`;

    continue;
  }

  art.qualifies = true;

  kept++;
}

// ======================================================
// RETURN RESULTS TO N8N
// ======================================================

return scored.map(article => ({

  json: {

    ...article,

    qualified: article.qualifies,

    status: article.qualifies
      ? "QUALIFIED"
      : "REJECTED",

    threshold: THRESHOLD,

    top_limit: TOP_N

  }

}));

/**
 * SELECT TOP 25 QUALIFIED AI NEWS
 * Input: V4 scoring results
 * Output: Top 25 qualified articles
 */

const TOP_N = 25;
const MIN_SCORE = 54;

const articles = $input.all().map(item => item.json);

const qualified = articles
  .filter(article =>
    article.qualified === true &&
    Number(article.score) >= MIN_SCORE
  )
  .sort((a, b) => Number(b.score) - Number(a.score));

const top25 = qualified.slice(0, TOP_N);

return top25.map((article, index) => ({
  json: {
    ...article,
    rank: index + 1,
    selected_for_digest: true,
    digest_status: "PENDING_EXTRACTION",
    article_url: article.url,
    processed_at: new Date().toISOString()
  }
}));

/**
 * AI NEWS AUTOMATION
 * CLEANING + VALIDATION V6
 *
 * Input node: Jina Ai extraction
 * Ranking node: Top 25 articles qualified
 *
 * V4 scores and ranking are preserved.
 */

const items = $input.all();
const MIN_WORDS = 250;

// ==========================================
// HELPERS
// ==========================================

function str(v) {
  return v == null ? "" : String(v);
}

function normalizeUrl(url) {
  return str(url)
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .replace(/[?#].*$/, "")
    .replace(/\/+$/, "");
}

function countWords(text) {
  return str(text).trim().split(/\s+/)
    .filter(Boolean).length;
}

function sourceFromUrl(url) {
  const u = str(url).toLowerCase();
  if (u.includes("marktechpost.com"))
    return "MarkTechPost";
  if (u.includes("techcrunch.com"))
    return "TechCrunch";
  if (u.includes("technologyreview.com"))
    return "MIT Technology Review";
  return "Unknown";
}

// ==========================================
// RESTORE ORIGINAL RANKING
// ==========================================

const ranked = $("Top 25 articles qualified")
  .all()
  .map(item => item.json);

const rankingMap = new Map();

for (const article of ranked) {
  const url = article.article_url || article.url;
  if (url) {
    rankingMap.set(normalizeUrl(url), article);
  }
}

// ==========================================
// FIND ARTICLE BODY START
// ==========================================

function removeMarkTechPostHeader(text, title) {
  const heading = str(title).trim();

  if (!heading || text.length < 1000) {
    return text;
  }

  const lower = text.toLowerCase();
  const target = heading.toLowerCase();

  // Restrict search to the initial website header.
  // Long cookie panels can precede the article.
  const searchLimit = Math.min(text.length, 35000);
  const matches = [];

  let pos = 0;

  while (true) {
    const found = lower.indexOf(target, pos);

    if (found < 0 || found >= searchLimit) {
      break;
    }

    matches.push(found);
    pos = found + target.length;
  }

  if (!matches.length) {
    return text;
  }

  // Find the heading followed by a byline or date.
  // This distinguishes the real article from
  // navigation, breadcrumbs and recommendations.
  let chosen = -1;

  for (const index of matches) {
    const after = text.slice(
      index + heading.length,
      index + heading.length + 350
    );

    if (
      /(?:^|\n)\s*By\s*(?:\n|[A-Z])/i.test(after) ||
      /\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+20\d{2}\b/i.test(after)
    ) {
      chosen = index;
    }
  }

  // If no byline is detected, use the last
  // occurrence in the header region.
  if (chosen < 0) {
    chosen = matches[matches.length - 1];
  }

  return text.slice(chosen);
}

// ==========================================
// REMOVE MARKTECHPOST AUTHOR BIO
// ==========================================

function removeAuthorBio(text) {
  const patterns = [
    /\n\s*Asif Razzaq is the CEO of Marktechpost\b/i,
    /\n\s*Asif Razzaq is the CEO of MarkTechPost\b/i,
    /\n\s*Asif Razzaq is the CEO of MarkTechPost AI Media\b/i
  ];

  let cut = text.length;

  for (const pattern of patterns) {
    const match = pattern.exec(text);
    if (match) {
      cut = Math.min(cut, match.index);
    }
  }

  text = text.slice(0, cut);

  // Remove standalone author name at end.
  text = text.replace(
    /\n\s*Asif Razzaq\s*$/i,
    ""
  );

  return text;
}

// ==========================================
// REMOVE FOOTERS
// ==========================================

function removeFooter(text, source) {
  if (source !== "MarkTechPost") {
    return text;
  }

  const patterns = [
    /^\s*YOU READ TO THE END\s*$/im,
    /^\s*RELATED ARTICLES(?: MORE FROM AUTHOR)?\s*$/im,
    /^\s*Previous article\s*$/im,
    /^\s*Next article\s*$/im,
    /^\s*Need to partner with us.*$/im
  ];

  let cut = text.length;

  for (const pattern of patterns) {
    const match = pattern.exec(text);
    if (match) {
      cut = Math.min(cut, match.index);
    }
  }

  return text.slice(0, cut);
}

// ==========================================
// REMOVE PROMOTIONS
// ==========================================

function removePromotions(text) {
  const patterns = [
    /AI DEV SIGNALS/i,
    /70,000\+ AI builders/i,
    /Get the AI releases that matter/i,
    /You're in\. Check your inbox/i,
    /You’re in\. Check your inbox/i,
    /Email address Subscribe free/i,
    /Model releases, open weights, agents and papers with code/i,
    /GPULeaderboard\.com chrome extension/i,
    /Subscribe to\s*our Newsletter/i,
    /join our\s*150k\+\s*ML SubReddit/i,
    /Add as a preferred source on Google/i,
    /google\.com\/preferences\/source/i,
    /Also,\s*feel free to follow us/i,
    /CookieLawInfoConsent/i,
    /^Cookie settings REJECT ACCEPT$/i,
    /^Necessary Always Active$/i,
    /^Powered by$/i,
    /^Search AI news/i,
    /When you purchase through links in our articles/i,
    /This doesn.t affect our editorial independence/i,
    /Sign up for.*newsletter/i,
    /Subscribe to.*newsletter/i,
    /^Advertisement$/i,
    /^Sponsored$/i,
    /^Share this article$/i
  ];

  return text.split("\n")
    .filter(line => {
      const s = line.trim();
      return !patterns.some(p => p.test(s));
    })
    .join("\n");
}

// ==========================================
// REMOVE MARKDOWN DECORATION
// ==========================================

function cleanMarkdown(text) {
  return text
    .replace(/!\[[^\]]*\]\([^)]+\)/g, "")
    .replace(/\[([^\]]+)\]\(https?:\/\/[^)]+\)/g, "$1")
    .replace(/\[\]\([^)]+\)/g, "")
    .replace(/^\s*#{1,6}\s+/gm, "")
    .replace(/^```[^\n]*$/gm, "")
    .replace(/\*\*/g, "")
    .replace(/^\s*\]?\(https?:\/\/[^\n]+\)\s*$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

// ==========================================
// COMPLETE ARTICLE CLEANING
// ==========================================

function cleanArticle(raw, source, title) {
  let text = str(raw)
    .replace(/\r\n?/g, "\n")
    .replace(/\u00a0/g, " ");

  if (source === "MarkTechPost") {
    text = removeMarkTechPostHeader(text, title);
  }

  text = removeFooter(text, source);
  text = removeAuthorBio(text);
  text = removePromotions(text);
  text = cleanMarkdown(text);

  // Remove isolated author byline at end.
  if (source === "MarkTechPost") {
    text = text.replace(
      /\n\s*Asif Razzaq\s*$/i,
      ""
    );
  }

  return text.replace(/\n{3,}/g, "\n\n").trim();
}

// ==========================================
// PROCESS ALL 25 ARTICLES
// ==========================================

return items.map((item, index) => {
  const response = item.json || {};
  const data = response.data || response;

  const jinaUrl = str(
    data.original_url ||
    data.url ||
    data.finalUrl ||
    ""
  ).trim();

  let original =
    rankingMap.get(normalizeUrl(jinaUrl));

  if (!original && data.finalUrl) {
    original = rankingMap.get(
      normalizeUrl(data.finalUrl)
    );
  }

  // If input already contains ranking fields,
  // preserve them when URL lookup fails.
  if (!original && data.score != null) {
    original = data;
  }

  original = original || {};

  const url =
    original.article_url ||
    original.url ||
    jinaUrl;

  const title = str(
    data.title ||
    original.title ||
    ""
  ).trim();

  const source =
    original.source ||
    sourceFromUrl(url);

  const publishedTime =
    data.published_time ||
    data.publishedTime ||
    data.metadata?.["article:published_time"] ||
    original.published_time ||
    null;

  const authorValue =
    data.author ||
    data.metadata?.author ||
    original.author ||
    null;

  const author = Array.isArray(authorValue)
    ? authorValue[0] || null
    : authorValue;

  const description = str(
    data.description ||
    original.description ||
    ""
  ).trim();

  const rawContent = str(data.content);

  const content = cleanArticle(
    rawContent,
    source,
    title
  );

  const words = countWords(content);

  const httpStatus =
    data.http_status ??
    data.httpStatus ??
    response.httpStatus ??
    null;

  const statusCode = Number(httpStatus);

  const redirectDetected =
    httpStatus != null &&
    statusCode >= 300 &&
    statusCode < 400;

  // ========================================
  // VALIDATION
  // ========================================

  const issues = [];

  if (!title) {
    issues.push("MISSING_TITLE");
  }

  if (!url) {
    issues.push("MISSING_URL");
  }

  if (!publishedTime) {
    issues.push("MISSING_PUBLICATION_DATE");
  }

  if (source === "Unknown") {
    issues.push("UNKNOWN_SOURCE");
  }

  if (words < MIN_WORDS) {
    issues.push("CONTENT_TOO_SHORT");
  }

  if (httpStatus != null && statusCode >= 400) {
    issues.push("HTTP_ERROR_" + statusCode);
  }

  const metadataMatched =
    Object.keys(original).length > 0;

  if (!metadataMatched) {
    issues.push("RANKING_METADATA_NOT_FOUND");
  }

  // Detect leftover website cookie sections.
  const residualNoise =
    /Cookie settings REJECT ACCEPT|Necessary cookies are absolutely essential|Cookie cookielawinfo-checkbox|Cookie _pxvid|Powered by\s+News Hub|Asif Razzaq is the CEO of Marktechpost/i
      .test(content);

  if (residualNoise) {
    issues.push("WEBSITE_NOISE_REMAINING");
  }

  const ready = issues.length === 0;

  // ========================================
  // FINAL OUTPUT
  // ========================================

  return {
    json: {
      // Original V4 scoring
      run_id: original.run_id ?? null,
      rank: original.rank ?? index + 1,
      score: original.score ?? null,
      qualified: original.qualified ?? null,
      qualifies: original.qualifies ?? null,
      threshold: original.threshold ?? null,
      breakdown: original.breakdown ?? null,
      reasons: original.reasons ?? [],
      cluster: original.cluster ?? null,

      // Article metadata
      title,
      source,
      url,
      published_time: publishedTime,
      author,
      description,

      // Clean article content
      content,
      word_count: words,

      // Extraction
      http_status: httpStatus,
      redirect_detected: redirectDetected,

      // Digest
      selected_for_digest:
        original.selected_for_digest ?? true,

      extraction_status:
        ready ? "READY_FOR_LLM" : "NEEDS_REVIEW",

      extraction_issues: issues,
      metadata_matched: metadataMatched,

      // Cleaning diagnostics
      original_word_count: countWords(rawContent),
      removed_word_count:
        Math.max(0, countWords(rawContent) - words)
    },

    pairedItem: {
      item: index
    }
  };
});

