function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function parseAI(raw) {
  let text = String(raw ?? "")
    .replace(/```json|```/gi, "")
    .trim();

  try {
    return JSON.parse(text);
  } catch (e) {}

  // Recover JSON missing its final closing brace.
  try {
    const open = (text.match(/\{/g) || []).length;
    const close = (text.match(/\}/g) || []).length;

    if (open > close && open - close <= 2) {
      return JSON.parse(text + "}".repeat(open - close));
    }
  } catch (e) {}

  // Recover summary and other available text.
  function extract(key) {
    const expression = new RegExp(
      '"' + key + '"\\s*:\\s*"((?:\\\\.|[^"\\\\])*)"',
      "s"
    );

    const match = text.match(expression);

    if (!match) return "";

    try {
      return JSON.parse('"' + match[1] + '"');
    } catch (e) {
      return match[1];
    }
  }

  const takeaways = [];
  const match = text.match(
    /"key_takeaways"\s*:\s*\[([\s\S]*?)\]/
  );

  if (match) {
    try {
      takeaways.push(
        ...JSON.parse("[" + match[1] + "]")
      );
    } catch (e) {}
  }

  return {
    summary: extract("summary"),
    key_takeaways: takeaways,
    why_it_matters: extract("why_it_matters")
  };
}

function formatDate(value) {
  if (!value) return "";

  const date = new Date(value);

  if (isNaN(date.getTime())) {
    return String(value);
  }

  return date.toLocaleDateString("en-IN", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "Asia/Kolkata"
  });
}

function safeURL(value) {
  const url = String(value || "").trim();
  return /^https?:\/\//i.test(url) ? url : "";
}

